(function () {
  'use strict';
  const chunkSet = {"title":"Story Elements","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-story-elements-q0151","version":3,"contentHash":"sha256:2d3121b30f9d89caf20b2424d1f7526be2159f8c3cbf4ddd42d704c8d5b449fc","question":"Read the story. Grade 5 developing story: Lena was at the classroom supply table when her group's poster tore right before the science fair. Lena felt the pressure of the moment, but she calmly taped the back, asked for a spare sheet, and divided the repair jobs. In the end, the group finished on time.\n\nWhich word best describes Lena?","choices":["impatient","careless","boastful","resourceful"],"correct":3,"studyAid":{"definition":"Character traits describe a person's personality or behavior based on the actions they take within a story.","example":"If a character shares their lunch, they are generous. If a character hides when it is their turn to help, they are shy.","strategyClue":"Look for specific actions the character takes in the story, then identify what those actions say about the person's personality.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: resourceful. Lena showed she was resourceful by finding creative solutions to problems, such as taping the poster and dividing the tasks to finish on time.","incorrect":[{"choice":"impatient","category":"mismatched character trait","reason":"The story says Lena acted 'calmly' when the poster tore, which is the opposite of being impatient."},{"choice":"careless","category":"mismatched character trait","reason":"Careless people make mistakes through lack of attention, but Lena fixed the poster and organized her group to succeed."},{"choice":"boastful","category":"mismatched character trait","reason":"Boastful people brag about themselves, but the story focuses only on Lena's helpful actions and problem-solving skills."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":151,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0152","version":3,"contentHash":"sha256:1540db9a636449a7631020291bc781817bee73b0ebf25cd0a3d2ec3925ca0d32","question":"Read the story. Grade 5 developing story: Mateo was at the school bus line when a younger student dropped a folder and papers scattered. Mateo felt the pressure of the moment, but Mateo stepped out of line, gathered the papers, and helped sort them by subject. In the end, the younger student smiled and found the missing homework.\n\nWhat is the story's main problem?","choices":["a younger student dropped a folder and papers scattered","Mateo wants to leave the setting before anything happens.","Mateo cannot remember anyone's name.","The story has no problem to solve."],"correct":0,"studyAid":{"definition":"The main problem (or conflict) in a story is the struggle or challenge that a character faces and tries to overcome.","example":"A lost dog, a broken bicycle, or a missing assignment are common story problems.","strategyClue":"Look for the sentence that describes something going wrong, breaking, or being lost, which then causes the character to take action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a younger student dropped a folder and papers scattered. This is the main problem because it is the initial event that disrupts the setting and creates a challenge requiring Mateo to act.","incorrect":["",{"choice":"Mateo wants to leave the setting before anything happens.","category":"misreading text events","reason":"The story shows Mateo stepping out of line to help, which contradicts the idea that he wants to leave the setting."},{"choice":"Mateo cannot remember anyone's name.","category":"unsupported by text","reason":"There is no mention of names or forgetting them in the passage, so this cannot be the problem."},{"choice":"The story has no problem to solve.","category":"identifying conflict","reason":"A problem is any event that disrupts the story's flow. Because the student's papers fell, there is a clear situation that needs to be fixed."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":152,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0153","version":3,"contentHash":"sha256:fb64821aa53b04bdc9ac9f70ed971308c0bcda18b71a4ae59ea71114dc6fff46","question":"Read the story. Grade 5 developing story: Priya was at the community garden when her bean plants wilted after several hot days. Priya felt the pressure of the moment, but she checked the soil, moved mulch around the stems, and changed the watering schedule. In the end, new green leaves appeared the next week.\n\nWhere does the story mainly take place?","choices":["inside a grocery store","the community garden","on a mountain trail","at a train station"],"correct":1,"studyAid":{"definition":"The setting is the time and place where the events of a story happen.","example":"A story about a knight is in a castle; a story about a swimmer is at a pool.","strategyClue":"Underline the specific nouns in the first sentence that describe the surroundings, and look for context clues like 'plants,' 'soil,' and 'mulch' throughout the paragraph.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the community garden. The text explicitly states at the beginning of the story that 'Priya was at the community garden' when the events occurred.","incorrect":[{"choice":"inside a grocery store","category":"setting inconsistency","reason":"The story describes bean plants, soil, and mulch, which are things found in a garden, not inside a grocery store."},"",{"choice":"on a mountain trail","category":"setting inconsistency","reason":"While a mountain trail is outdoors, the presence of specific gardening tasks like moving mulch around stems indicates the setting is a garden."},{"choice":"at a train station","category":"setting inconsistency","reason":"Train stations have tracks and platforms, whereas the characters here are caring for plants in soil, which matches a garden setting."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":153,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0154","version":3,"contentHash":"sha256:ef6eceaea9b016362f717fae75ea0df4062592ae381760166f595f855de08f58","question":"Read the story. Grade 5 developing story: Noah was at the music room when he kept missing the same measure during recorder practice. Noah felt the pressure of the moment, but he slowed the song down, clapped the rhythm, and practiced four notes at a time. In the end, he played the measure correctly during rehearsal.\n\nHow is the problem resolved?","choices":["An adult solves the problem without the character doing anything.","Noah decides the problem is impossible.","he played the measure correctly during rehearsal","The story ends before the problem is addressed."],"correct":2,"studyAid":{"definition":"A story's resolution is how the main character fixes the problem or achieves their goal by the end of the narrative.","example":"Problem: A lost key. Resolution: Retracing steps to find it under the rug.","strategyClue":"Look for the sentence that describes the final result of the character's actions. Ask yourself, 'Did the character give up, get help, or use a plan to change the outcome?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: he played the measure correctly during rehearsal. The text states that by breaking the practice into smaller sections and working on the rhythm, Noah was eventually able to play the difficult measure successfully.","incorrect":[{"choice":"An adult solves the problem without the character doing anything.","category":"misinterpreting character agency","reason":"The story shows Noah taking active steps to fix his mistake, such as clapping the rhythm. He solves the problem himself through practice, not with help from an adult."},{"choice":"Noah decides the problem is impossible.","category":"contradictory outcome","reason":"Noah does not give up; instead, he uses a specific strategy of slowing down the song and working on small groups of notes to master the section."},"",{"choice":"The story ends before the problem is addressed.","category":"overlooking narrative resolution","reason":"The story explicitly says that after his practice, Noah played the measure correctly, which means the problem was addressed and resolved."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":154,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0155","version":3,"contentHash":"sha256:42f1038f0b5102c6a9db24572b16e48fe6fe2400700e18c5bddef1dc415e28d8","question":"Read the story. Grade 5 developing story: Ari was at the lunch table when two friends argued about who should choose the game at recess. Ari felt the pressure of the moment, but Ari suggested each friend pick one round and then vote on a final round. In the end, both friends agreed and the argument ended.\n\nWhat most likely motivates Ari's actions?","choices":["Ari is trying to avoid helping anyone.","Ari wants to make the problem worse.","Ari hopes nobody notices the problem.","Ari wanted both friends to feel heard."],"correct":3,"studyAid":{"definition":"Motivation is the 'why' behind a character's actions. To find it, look for how a character's words or deeds help achieve a specific goal or result.","example":"If a character shares their lunch, their motivation is likely kindness; if a character studies hard, their motivation is to get a good grade.","strategyClue":"Look at the outcome of the character's suggestion—did it bring peace or conflict? The result of the action often reveals the character's underlying goal.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Ari wanted both friends to feel heard. By suggesting a compromise where each friend gets a turn and they share the final decision, Ari shows a desire to keep the peace and validate both perspectives in the argument.","incorrect":[{"choice":"Ari is trying to avoid helping anyone.","category":"Misinterpretation of motivation","reason":"If Ari were avoiding the problem, they would have walked away. Instead, Ari offered a specific solution to help the friends reach an agreement."},{"choice":"Ari wants to make the problem worse.","category":"Contradictory behavior","reason":"The story shows that the argument ended because of Ari's suggestion, which proves that Ari intended to solve the problem, not escalate it."},{"choice":"Ari hopes nobody notices the problem.","category":"Unsubstantiated claim","reason":"The text states Ari felt the pressure of the moment and actively intervened; this shows Ari was paying close attention and chose to be involved."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":155,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0156","version":3,"contentHash":"sha256:74057876f02158ee1c6d8068bab98973e09218ca19c1cd18adbb42ffc309dca8","question":"Read the story. Grade 5 developing story: Sofia was at the school art show when she worried that her painting looked different from everyone else's. Sofia felt the pressure of the moment, but she listened as visitors asked about her unusual colors and bold shapes. In the end, she began to feel proud of her own style.\n\nWhich word best describes Sofia?","choices":["creative","careless","boastful","impatient"],"correct":0,"studyAid":{"definition":"To find a character trait, look for clues in the text about how a character thinks, acts, or feels.","example":"If a character shares their lunch, they are kind. If they jump into a deep lake without knowing how to swim, they might be reckless.","strategyClue":"Highlight the specific actions or feelings Sofia displays in the text, then match those actions to the definitions of the four choices provided.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: creative. Sofia used 'unusual colors' and 'bold shapes' to create a unique style, which shows she is creative.","incorrect":["",{"choice":"careless","category":"misinterpreted character traits","reason":"Being careless means not paying attention to detail. Sofia’s focus on her colors and shapes shows she put a lot of thought into her painting."},{"choice":"boastful","category":"misinterpreted character traits","reason":"A boastful person brags about themselves. Sofia was actually worried and humble until she realized her style was special."},{"choice":"impatient","category":"misinterpreted character traits","reason":"An impatient person does not want to wait. The story shows Sofia listening carefully to the visitors rather than rushing away or getting frustrated."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":156,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0157","version":3,"contentHash":"sha256:4ecf05b0d16d60df861eae37085ef9ba7e030a2c30b1b59b872ffd7340a46b62","question":"Read the story. Grade 5 developing story: Evan was at the soccer field when his team was losing and he had not scored. Evan felt the pressure of the moment, but he passed to a teammate who had a clear shot instead of kicking from a bad angle. In the end, the teammate scored and the team cheered together.\n\nWhat is the story's main problem?","choices":["Evan wants to leave the setting before anything happens.","his team was losing and he had not scored","Evan cannot remember anyone's name.","The story has no problem to solve."],"correct":1,"studyAid":{"definition":"The 'main problem' is the central conflict or struggle that the characters face throughout the story. It is the obstacle that stands in the way of the goal.","example":"A character is lost in the woods; a girl cannot find her lost cat; two friends are arguing over a toy.","strategyClue":"Look for the sentence that describes what is going wrong for the main character. Ask yourself, 'What is the specific challenge the character needs to fix or change?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: his team was losing and he had not scored. A main problem in a story is the central challenge or conflict a character faces. In this story, Evan's team is down in the score and he personally hasn't helped by scoring, creating the conflict he must overcome.","incorrect":[{"choice":"Evan wants to leave the setting before anything happens.","category":"Unsupported plot detail","reason":"The text never mentions Evan wanting to leave; instead, he stays involved in the game and passes the ball to help his team."},"",{"choice":"Evan cannot remember anyone's name.","category":"Unsupported plot detail","reason":"The story does not mention any confusion about names or teammates. This detail is not found in the text provided."},{"choice":"The story has no problem to solve.","category":"Misidentified story conflict","reason":"Every story usually contains a challenge. Here, the team losing and Evan missing goals creates a clear pressure-filled situation that he must resolve."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":157,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0158","version":3,"contentHash":"sha256:401a530f738e3d03fe3a07bb0896b270821f1c255511d62c61d4593b298443f9","question":"Read the story. Grade 5 developing story: Mina was at the hallway before the spelling bee when she felt nervous after hearing older students practice difficult words. Mina felt the pressure of the moment, but she breathed slowly, reviewed her word cards, and remembered how much she had studied. In the end, she walked onto the stage feeling steady.\n\nWhere does the story mainly take place?","choices":["on a mountain trail","inside a grocery store","the hallway before the spelling bee","at a train station"],"correct":2,"studyAid":{"definition":"The setting is the time and place where a story happens. To find the setting, look for clues about locations or specific activities mentioned in the text.","example":"If a character is putting on a swimsuit, the setting is likely a pool or beach. If a character is checking out a library book, the setting is likely a school or library.","strategyClue":"Highlight the sentence in the text that tells you exactly where the character is standing at the beginning of the story.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the hallway before the spelling bee. The story explicitly states that 'Mina was at the hallway before the spelling bee' and later mentions she 'walked onto the stage', which is where a spelling bee takes place.","incorrect":[{"choice":"on a mountain trail","category":"setting mismatch","reason":"There is no mention of outdoor scenery, hiking, or trails in the text. The story focuses on nervousness before a spelling bee."},{"choice":"inside a grocery store","category":"setting mismatch","reason":"The story mentions reviewing word cards and walking onto a stage, which are activities related to a school event, not shopping for groceries."},"",{"choice":"at a train station","category":"setting mismatch","reason":"Nothing in the story mentions tracks, trains, or traveling. The setting is specifically linked to the location of the spelling bee."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":158,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0159","version":3,"contentHash":"sha256:454df16b0446f469852d9e1a92dfb55c3284ae3bc8cb9119a8ad231a07701bb1","question":"Read the story. Grade 5 developing story: Caleb was at the animal shelter when a shy dog hid whenever visitors came near. Caleb felt the pressure of the moment, but Caleb sat quietly nearby each week and let the dog approach when ready. In the end, the dog eventually rested its head beside him.\n\nHow is the problem resolved?","choices":["The story ends before the problem is addressed.","Caleb decides the problem is impossible.","An adult solves the problem without the character doing anything.","the dog eventually rested its head beside him"],"correct":3,"studyAid":{"definition":"The resolution is the part of the story where the conflict is settled or the problem is solved at the very end.","example":"If a girl loses her toy and spends the day looking for it, finding the toy under the bed is the resolution.","strategyClue":"Look at the very last sentence of the story. Identify what changed in the character's situation from the beginning to the end, then choose the option that describes that final successful change.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the dog eventually rested its head beside him. The resolution of a story is the final outcome where the main problem is solved. Since the problem was the dog being shy and afraid of visitors, the dog choosing to rest its head by Caleb shows it finally feels safe.","incorrect":[{"choice":"The story ends before the problem is addressed.","category":"misreading story progression","reason":"The story has a clear ending where the dog's behavior changes. It does not stop before the shy dog makes progress."},{"choice":"Caleb decides the problem is impossible.","category":"misinterpreting character actions","reason":"Caleb does not give up. Instead, he shows patience by sitting nearby each week, which leads to the dog approaching him."},{"choice":"An adult solves the problem without the character doing anything.","category":"misidentifying story resolution","reason":"The character, Caleb, actively solves the problem by being patient and quiet. No other characters are involved in this resolution."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":159,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0160","version":3,"contentHash":"sha256:1a316dec0e447e3f8a3ce46a6c0ac9108cef601ab9a60f7a4698a65f92b414f1","question":"Read the story. Grade 5 developing story: Jada was at a rainy field trip when the outdoor scavenger hunt had to be canceled. Jada felt the pressure of the moment, but she helped classmates create an indoor museum hunt using exhibit clues. In the end, the class discovered details they might have missed.\n\nWhat most likely motivates Jada's actions?","choices":["She wanted the trip to stay interesting even after plans changed.","Jada wants to make the problem worse.","Jada hopes nobody notices the problem.","Jada is trying to avoid helping anyone."],"correct":0,"studyAid":{"definition":"A character's motivation is the reason they act in a certain way, usually revealed by what they do or say in response to a problem.","example":"If a student shares their lunch with someone who forgot theirs, the motivation is kindness. If a character studies hard for a test, the motivation is wanting to succeed.","strategyClue":"Look at the character's reaction to a change or challenge. Ask yourself, 'Is this action helpful or hurtful?' and then look for the answer choice that matches that positive or negative behavior.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She wanted the trip to stay interesting even after plans changed. Jada's actions—creating a new museum hunt when the outdoor one was canceled—show that she is taking initiative to turn a disappointing situation into a fun, engaging experience for her classmates.","incorrect":["",{"choice":"Jada wants to make the problem worse.","category":"misinterpreting character motive","reason":"Creating a new scavenger hunt is a helpful, constructive action, not a destructive one meant to worsen the situation."},{"choice":"Jada hopes nobody notices the problem.","category":"ignoring character action","reason":"Jada does not hide or ignore the canceled trip; instead, she actively engages with her classmates to start a new activity, showing she is facing the problem head-on."},{"choice":"Jada is trying to avoid helping anyone.","category":"opposite character trait","reason":"The text explicitly states that she 'helped classmates' create a new activity, which proves she is actively trying to assist others."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":160,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0161","version":3,"contentHash":"sha256:7af2b329e3a34d47277d20b1645729ee81951a41927835c3b034fcede8d5fccf","question":"Read the story. Grade 5 developing story: Omar was at the computer lab when his slideshow disappeared when the program froze. Omar felt the pressure of the moment, but he checked the autosave folder and rebuilt two missing slides from his notes. In the end, his presentation was ready before class ended.\n\nWhich word best describes Omar?","choices":["careless","determined","boastful","impatient"],"correct":1,"studyAid":{"definition":"A character trait is a quality that describes a character's personality or behavior. To identify a trait, look at what the character does or how they react to a problem.","example":"If a character shares their lunch with a hungry friend, they are 'generous.' If a character keeps trying to fix a broken toy instead of throwing it away, they are 'persistent.'","strategyClue":"Look for the specific actions the character takes when faced with a challenge. Ask yourself, 'What do these actions show about how the character handles difficulty?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: determined. Omar showed he was determined because he did not give up when his work disappeared; instead, he took action by checking the autosave folder and rebuilding his slides.","incorrect":[{"choice":"careless","category":"mismatched personality trait","reason":"Careless means not paying attention to detail. Omar was the opposite—he was careful enough to keep notes and check his autosave folder."},"",{"choice":"boastful","category":"mismatched personality trait","reason":"Boastful means talking too much about one's own success. Nothing in the story suggests Omar bragged about his work."},{"choice":"impatient","category":"mismatched personality trait","reason":"Impatient means wanting things to happen faster and getting annoyed easily. Omar stayed calm and focused on solving the problem, which shows patience."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":161,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0162","version":3,"contentHash":"sha256:f15677bf558b89389edfe6caaf527fd14a6bcc431b8c7ef8855f4fb1e56e13c6","question":"Read the story. Grade 5 developing story: Nora was at the neighborhood sidewalk when an elderly neighbor struggled to carry groceries up the steps. Nora felt the pressure of the moment, but Nora asked permission, carried two light bags, and held the gate open. In the end, the neighbor thanked her and invited her to pick tomatoes later.\n\nWhat is the story's main problem?","choices":["Nora cannot remember anyone's name.","Nora wants to leave the setting before anything happens.","an elderly neighbor struggled to carry groceries up the steps","The story has no problem to solve."],"correct":2,"studyAid":{"definition":"The main problem is the challenge or obstacle a character faces in a story. It is the reason the main character takes action.","example":"A lost puppy needs a home; a character cannot find their keys; a student struggles with a difficult math problem.","strategyClue":"Ask yourself, 'What is the character trying to fix or help?' Look for the specific moment where someone is having a hard time or is in need of assistance.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: an elderly neighbor struggled to carry groceries up the steps. A problem in a story is the conflict or challenge that a character faces; here, the neighbor's struggle to manage the groceries creates the situation that requires Nora to act.","incorrect":[{"choice":"Nora cannot remember anyone's name.","category":"unsupported plot detail","reason":"The story never mentions Nora having trouble with names. Always look for evidence directly stated in the text before choosing a problem."},{"choice":"Nora wants to leave the setting before anything happens.","category":"contradictory action","reason":"The story says Nora felt the pressure and chose to stay and help. She does not try to leave, so this cannot be the problem."},"",{"choice":"The story has no problem to solve.","category":"missing internal conflict","reason":"Even small stories have a challenge. A problem is any obstacle someone faces, and helping the neighbor was the clear challenge Nora addressed."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":162,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0163","version":3,"contentHash":"sha256:098c462262382f6154ed8122ed2622b8e08bef1fc1daf2e726d608ca64b33730","question":"Read the story. Grade 5 developing story: Ben was at the chess club table when he lost three games in a row. Ben felt the pressure of the moment, but he asked his opponent to show the move that trapped his queen. In the end, he used the lesson to avoid the trap in the next game.\n\nWhere does the story mainly take place?","choices":["at a train station","inside a grocery store","on a mountain trail","the chess club table"],"correct":3,"studyAid":{"definition":"The 'setting' of a story is the time and place where the events happen. Look for specific nouns that describe a location.","example":"If a story says 'He kicked the ball on the grass,' the setting is a field or park, not a kitchen.","strategyClue":"Locate the sentence in the text that mentions a place or location, then compare that noun to the options provided.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the chess club table. The text explicitly states, 'Ben was at the chess club table,' which identifies the specific location of the events described.","incorrect":[{"choice":"at a train station","category":"misreading text details","reason":"The story mentions a chess club, not a train station. Always scan the opening sentence for keywords that indicate setting."},{"choice":"inside a grocery store","category":"incorrect story setting","reason":"There is no mention of shopping or groceries. Look for the specific location name provided in the first sentence."},{"choice":"on a mountain trail","category":"ignoring textual evidence","reason":"The characters are sitting at a table playing a game, which is not an outdoor trail. Make sure to choose the location explicitly named in the passage."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":163,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0164","version":3,"contentHash":"sha256:43688ae4eec6e3fbe037d2b80111e13a7f1c8e7245379c4c6961384c6def3ab4","question":"Read the story. Grade 5 developing story: Talia was at the school hallway after dismissal when she found a wallet with lunch money and a student ID. Talia felt the pressure of the moment, but she took it to the office before leaving for practice. In the end, the owner got the wallet back before the buses left.\n\nHow is the problem resolved?","choices":["the owner got the wallet back before the buses left","Talia decides the problem is impossible.","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":0,"studyAid":{"definition":"The resolution of a story is the final outcome or how the conflict is worked out.","example":"A lost dog is found by his owner (resolution); a contest winner is announced (resolution).","strategyClue":"Look for the final action in the paragraph that settles the original conflict mentioned in the beginning of the text.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the owner got the wallet back before the buses left. This choice directly identifies the final action described in the text that shows the conflict was settled.","incorrect":["",{"choice":"Talia decides the problem is impossible.","category":"incorrect plot interpretation","reason":"This is incorrect because Talia actively solves the problem by taking the wallet to the office, rather than giving up."},{"choice":"An adult solves the problem without the character doing anything.","category":"incorrect character agency","reason":"This is incorrect because the story specifically states that Talia took the wallet to the office herself."},{"choice":"The story ends before the problem is addressed.","category":"misreading text structure","reason":"This is incorrect because the final sentence explicitly describes the successful resolution of the wallet being returned."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":164,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0165","version":4,"contentHash":"sha256:edb0e05eae3336297d8f5ee541f2d430ad213407aceb043da3a0484f1e788c66","question":"Read the story. Grade 5 developing story: Diego was at the creek behind the park when he saw that stepping stones had shifted after heavy rain. Diego felt the pressure of the moment, but he warned younger children to use the bridge and told a ranger. In the end, the crossing was closed until it could be repaired.\n\nWhat most likely motivates Diego's actions?","choices":["Diego wants to make the problem worse.","He wanted others to stay safe.","Diego hopes nobody notices the problem.","Diego is trying to avoid helping anyone."],"correct":1,"studyAid":{"definition":"A character's motivation is the reason why they say or do things in a story, often revealed through their specific actions.","example":"If a character shares their lunch, their motivation might be kindness. If a character studies hard, their motivation might be to get an 'A'.","strategyClue":"Look at what the character actually does. Ask yourself, 'Why would someone do these things?' and choose the option that matches the helpful or positive result of those actions.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: He wanted others to stay safe. Diego's decision to warn younger children about the dangerous stones and report the issue to a ranger shows his primary goal is to prevent others from getting hurt.","incorrect":[{"choice":"Diego wants to make the problem worse.","category":"misinterpreting character intent","reason":"Warning children and telling a ranger are helpful actions, not harmful ones. Making the problem worse would involve hiding the danger or encouraging kids to use the broken path."},"",{"choice":"Diego hopes nobody notices the problem.","category":"ignoring character actions","reason":"If Diego wanted the problem to go unnoticed, he would not have taken the time to speak to the children or find a park ranger to report the damage."},{"choice":"Diego is trying to avoid helping anyone.","category":"contradicting text evidence","reason":"The text shows Diego taking specific steps to help others. Avoiding responsibility would mean doing nothing, but Diego actively works to keep the area safe."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":165,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0166","version":3,"contentHash":"sha256:74a9e089635a72dc8b7e7777d22c5f749aac3fdd20645ea75dd264c304924405","question":"Read the story. Grade 5 challenge story: Lena was at the classroom supply table when her group's poster tore right before the science fair. At first, the situation seemed discouraging. Instead of reacting too quickly, Lena thought about what mattered most: she wanted her group to feel ready instead of giving up. Then she calmly taped the back, asked for a spare sheet, and divided the repair jobs. In the end, the group finished on time.\n\nWhich word best describes Lena?","choices":["boastful","careless","resourceful","impatient"],"correct":2,"studyAid":{"definition":"To identify a character trait, look at what the character actually does and says in the story rather than just guessing based on how you feel.","example":"If a character shares their lunch, they are generous. If a character makes a mess and doesn't clean it, they are messy.","strategyClue":"Look back at the actions Lena takes in the story and ask yourself what specific quality those actions demonstrate.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: resourceful. Lena is described as resourceful because she used her problem-solving skills to fix the poster, divide tasks, and complete the project on time despite the setback.","incorrect":[{"choice":"boastful","category":"mismatched personality trait","reason":"Lena was focused on fixing the poster for her group, not showing off or bragging about her skills to others."},{"choice":"careless","category":"opposite personality trait","reason":"Lena was very careful and thoughtful; she didn't react too quickly and made sure the group felt ready."},"",{"choice":"impatient","category":"opposite personality trait","reason":"The story explicitly says Lena acted 'calmly' instead of reacting too quickly, which is the opposite of being impatient."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":166,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0167","version":3,"contentHash":"sha256:0adb9ba97f67f554380676c20f940ad1c186b5eb45361a86c48d0b0ab6399a3a","question":"Read the story. Grade 5 challenge story: Mateo was at the school bus line when a younger student dropped a folder and papers scattered. At first, the situation seemed discouraging. Instead of reacting too quickly, Mateo thought about what mattered most: he noticed someone needed help more than he needed to keep his place. Then Mateo stepped out of line, gathered the papers, and helped sort them by subject. In the end, the younger student smiled and found the missing homework.\n\nWhat is the story's main problem?","choices":["The story has no problem to solve.","Mateo wants to leave the setting before anything happens.","Mateo cannot remember anyone's name.","a younger student dropped a folder and papers scattered"],"correct":3,"studyAid":{"definition":"The main problem of a story is the conflict or challenge that the characters must face or resolve.","example":"A character loses their house key (problem: cannot get inside); a character gets lost in a big city (problem: cannot find their way home).","strategyClue":"Look for a moment in the story where something goes wrong or a character faces an obstacle. Ask yourself, 'What event caused the character to take action?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a younger student dropped a folder and papers scattered. The main problem is the conflict that initiates the action in the story; here, the physical accident created a situation that required Mateo's help.","incorrect":[{"choice":"The story has no problem to solve.","category":"misidentifying plot conflict","reason":"Stories typically revolve around a struggle or challenge. Dropping papers and homework created a small obstacle for the younger student, which is the problem Mateo solves."},{"choice":"Mateo wants to leave the setting before anything happens.","category":"misinterpreting character motivation","reason":"The text does not state that Mateo wants to leave. Instead, he chooses to step out of his line to assist someone else, showing his character rather than a desire to escape."},{"choice":"Mateo cannot remember anyone's name.","category":"unsupported plot detail","reason":"This information is never mentioned in the story. When looking for the main problem, stick only to the events that are explicitly stated in the text."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":167,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0168","version":3,"contentHash":"sha256:8b5d154373c9786ca67b7a84174d59fec5a7acc641856fdb743ec08d6fdf2947","question":"Read the story. Grade 5 challenge story: Priya was at the community garden when her bean plants wilted after several hot days. At first, the situation seemed discouraging. Instead of reacting too quickly, Priya thought about what mattered most: she wanted to understand what the plants needed before trying a solution. Then she checked the soil, moved mulch around the stems, and changed the watering schedule. In the end, new green leaves appeared the next week.\n\nWhere does the story mainly take place?","choices":["the community garden","inside a grocery store","on a mountain trail","at a train station"],"correct":0,"studyAid":{"definition":"The setting is the time and place where the events of a story happen.","example":"Setting: A busy school hallway. Setting: A quiet bedroom at night.","strategyClue":"Skim the first two sentences for nouns that describe a location and cross-reference them with the actions performed by the characters.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the community garden. The text explicitly states, 'Priya was at the community garden,' which establishes the setting of the story.","incorrect":["",{"choice":"inside a grocery store","category":"incorrect story setting","reason":"The story mentions plants, soil, and mulch, which are found in a garden, not a grocery store."},{"choice":"on a mountain trail","category":"incorrect story setting","reason":"Although this is outdoors, there is no mention of climbing or hiking on a trail; the focus is on gardening tasks."},{"choice":"at a train station","category":"incorrect story setting","reason":"There are no trains, tracks, or passengers mentioned in the story. The actions described are related to plant care."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":168,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0169","version":3,"contentHash":"sha256:f49e60d5eb41a1188255ebfb438597da853b17d45ce6da334c9eb9aa1bf00244","question":"Read the story. Grade 5 challenge story: Noah was at the music room when he kept missing the same measure during recorder practice. At first, the situation seemed discouraging. Instead of reacting too quickly, Noah thought about what mattered most: he wanted to improve even after the mistake felt frustrating. Then he slowed the song down, clapped the rhythm, and practiced four notes at a time. In the end, he played the measure correctly during rehearsal.\n\nHow is the problem resolved?","choices":["Noah decides the problem is impossible.","he played the measure correctly during rehearsal","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":1,"studyAid":{"definition":"A solution to a story's problem is the final result or action that fixes the challenge the main character faces.","example":"If a character is hungry and makes a sandwich, the sandwich-making is the resolution. If they are lost and ask for directions, the directions are the resolution.","strategyClue":"Scan the end of the text for words like 'in the end,' 'finally,' or 'then' to locate where the character's struggle reaches a conclusion.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: he played the measure correctly during rehearsal. The text explicitly states that Noah's persistence in slowing down the song and practicing in small sections led to him playing the measure correctly by the end of the story.","incorrect":[{"choice":"Noah decides the problem is impossible.","category":"misreading text evidence","reason":"This contradicts the text, which says Noah wanted to improve and took steps to practice the notes rather than giving up."},"",{"choice":"An adult solves the problem without the character doing anything.","category":"incorrect plot summary","reason":"The story describes Noah taking specific actions—clapping the rhythm and practicing small chunks—to solve the problem himself, rather than an adult doing it for him."},{"choice":"The story ends before the problem is addressed.","category":"ignoring final outcomes","reason":"The final sentence of the passage clearly describes the outcome of Noah's practice, showing that the problem was indeed addressed and solved."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":169,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0170","version":3,"contentHash":"sha256:aa2dc4a3a9770908c2b10c263089b48947b4e930b5cec1a42f2135cb64a79f4a","question":"Read the story. Grade 5 challenge story: Ari was at the lunch table when two friends argued about who should choose the game at recess. At first, the situation seemed discouraging. Instead of reacting too quickly, Ari thought about what mattered most: ari wanted both friends to feel heard. Then Ari suggested each friend pick one round and then vote on a final round. In the end, both friends agreed and the argument ended.\n\nWhat most likely motivates Ari's actions?","choices":["Ari hopes nobody notices the problem.","Ari wants to make the problem worse.","Ari wanted both friends to feel heard.","Ari is trying to avoid helping anyone."],"correct":2,"studyAid":{"definition":"Character motivation is the reason behind a character's actions. It is often found by looking for clues in the text about what the character thinks or wants.","example":"If a character shares their snack, their motivation might be 'being kind.' If a character studies hard, their motivation might be 'wanting an A.'","strategyClue":"Scan the text for the sentence that follows the character's internal thought process or key decision-making moment to find their core reason for acting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Ari wanted both friends to feel heard. The text explicitly states that Ari thought about what mattered most, which was ensuring that both friends had their perspectives valued and understood.","incorrect":[{"choice":"Ari hopes nobody notices the problem.","category":"mismatched character motivation","reason":"This choice contradicts the text because Ari actively steps in to address the argument rather than hiding from it or hoping it goes unnoticed."},{"choice":"Ari wants to make the problem worse.","category":"contrary to evidence","reason":"Ari's actions are meant to resolve the conflict by suggesting a fair compromise, which is the exact opposite of trying to escalate or worsen the argument."},"",{"choice":"Ari is trying to avoid helping anyone.","category":"misinterpreted intent","reason":"Ari takes time to think before acting and offers a solution to help both friends. This choice ignores Ari's clear effort to intervene and assist."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":170,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0171","version":3,"contentHash":"sha256:3c5ad031f163785c6544181bf37a4ed72dc69f179bd257683e26e6a9ab21b48c","question":"Read the story. Grade 5 challenge story: Sofia was at the school art show when she worried that her painting looked different from everyone else's. At first, the situation seemed discouraging. Instead of reacting too quickly, Sofia thought about what mattered most: she wanted her work to show what she imagined. Then she listened as visitors asked about her unusual colors and bold shapes. In the end, she began to feel proud of her own style.\n\nWhich word best describes Sofia?","choices":["impatient","careless","boastful","creative"],"correct":3,"studyAid":{"definition":"To infer a character trait, look for evidence in the text that describes a person's actions, thoughts, and feelings.","example":"If a character shares their toys, they are generous. If a character cries when they lose, they might be sensitive.","strategyClue":"Highlight specific phrases in the text that describe how Sofia acts or thinks, then look for a trait that matches those specific behaviors.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: creative. The text describes Sofia using 'unusual colors' and 'bold shapes,' and notes her desire to 'show what she imagined.' These qualities demonstrate originality and the ability to express her own unique style, which are traits of a creative person.","incorrect":[{"choice":"impatient","category":"misunderstanding character traits","reason":"The text actually states that Sofia avoided 'reacting too quickly,' which shows she was being thoughtful and patient rather than impatient."},{"choice":"careless","category":"misunderstanding character traits","reason":"Sofia put deep thought into what 'mattered most' and felt proud of her work, which is the opposite of being careless or unconcerned with quality."},{"choice":"boastful","category":"misunderstanding character traits","reason":"There is no evidence in the story of Sofia bragging or acting arrogant; instead, she focused on her personal artistic vision and how she felt about it herself."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":171,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0172","version":3,"contentHash":"sha256:abf766ec1c4f81b6d681d9ce2103a7357563219e457384304126d9faa6371403","question":"Read the story. Grade 5 challenge story: Evan was at the soccer field when his team was losing and he had not scored. At first, the situation seemed discouraging. Instead of reacting too quickly, Evan thought about what mattered most: he cared more about helping the team than being the scorer. Then he passed to a teammate who had a clear shot instead of kicking from a bad angle. In the end, the teammate scored and the team cheered together.\n\nWhat is the story's main problem?","choices":["his team was losing and he had not scored","Evan wants to leave the setting before anything happens.","Evan cannot remember anyone's name.","The story has no problem to solve."],"correct":0,"studyAid":{"definition":"The main problem (or conflict) is the challenge or obstacle that the main character faces in a story that they must try to solve.","example":"A character stuck in a storm, a hero needing to stop a villain, or a student trying to finish a hard project.","strategyClue":"Look for a sentence early in the story that describes something going wrong or a difficult situation the character finds themselves in. Ask yourself, 'What is making life hard for the main character right now?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: his team was losing and he had not scored. This is the main problem because it creates the conflict that Evan must overcome through his actions and attitude.","incorrect":["",{"choice":"Evan wants to leave the setting before anything happens.","category":"not in the text","reason":"The story never mentions Evan wanting to leave; instead, it describes his focus on helping the team win."},{"choice":"Evan cannot remember anyone's name.","category":"unsupported detail","reason":"There is no information in the story about Evan forgetting names. This choice does not relate to the conflict presented."},{"choice":"The story has no problem to solve.","category":"misidentifying story conflict","reason":"Every story usually has a conflict or obstacle. In this case, the team losing and Evan missing a goal creates a clear challenge for the characters."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":172,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0173","version":3,"contentHash":"sha256:12f4ac69e2f057174195371c9e392643bd7660f4a1edc081657fad01e2778d09","question":"Read the story. Grade 5 challenge story: Mina was at the hallway before the spelling bee when she felt nervous after hearing older students practice difficult words. At first, the situation seemed discouraging. Instead of reacting too quickly, Mina thought about what mattered most: she wanted to manage her nerves so she could do her best. Then she breathed slowly, reviewed her word cards, and remembered how much she had studied. In the end, she walked onto the stage feeling steady.\n\nWhere does the story mainly take place?","choices":["inside a grocery store","the hallway before the spelling bee","on a mountain trail","at a train station"],"correct":1,"studyAid":{"definition":"The setting is where and when a story takes place, often revealed through clues about the surroundings or the characters' activities.","example":"If characters are wearing space suits, the setting is likely space. If they are buying milk, the setting is likely a store.","strategyClue":"Scan the first sentence of the passage for place names or nouns that describe a location, as authors often state the setting early on.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the hallway before the spelling bee. The text explicitly states that Mina was at the hallway before the spelling bee, which serves as the setting for the events leading up to her performance.","incorrect":[{"choice":"inside a grocery store","category":"incorrect setting detail","reason":"The story never mentions groceries or a store. The characters are focused on studying words, not shopping for food."},"",{"choice":"on a mountain trail","category":"incorrect setting detail","reason":"The story mentions walking onto a stage, which confirms an indoor school or auditorium setting, not an outdoor hiking trail."},{"choice":"at a train station","category":"incorrect setting detail","reason":"There is no mention of trains, tickets, or travel. The focus is entirely on the atmosphere of a competition."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":173,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0174","version":3,"contentHash":"sha256:da6b06fec88e3a7fcb2a5b72c8751dc3fe7d164441248f5378f3e367110cc0e8","question":"Read the story. Grade 5 challenge story: Caleb was at the animal shelter when a shy dog hid whenever visitors came near. At first, the situation seemed discouraging. Instead of reacting too quickly, Caleb thought about what mattered most: he wanted the dog to feel safe, not rushed. Then Caleb sat quietly nearby each week and let the dog approach when ready. In the end, the dog eventually rested its head beside him.\n\nHow is the problem resolved?","choices":["An adult solves the problem without the character doing anything.","Caleb decides the problem is impossible.","the dog eventually rested its head beside him","The story ends before the problem is addressed."],"correct":2,"studyAid":{"definition":"The resolution of a story is the final outcome where the main problem is solved or the conflict is settled.","example":"If a character is lost, the resolution is them finding their way home; if a character is angry, the resolution is them making amends.","strategyClue":"Look at the final two sentences of the text. Ask yourself: 'What action did the character take, and how did the situation change because of it?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the dog eventually rested its head beside him. The resolution occurs when Caleb's patient approach succeeds, as indicated by the final sentence where the dog demonstrates trust by resting its head beside him.","incorrect":[{"choice":"An adult solves the problem without the character doing anything.","category":"misidentified character action","reason":"The story explicitly describes Caleb taking action by sitting quietly each week. The dog's change in behavior is a result of Caleb's persistence, not an outside adult."},{"choice":"Caleb decides the problem is impossible.","category":"misreading the character's attitude","reason":"Caleb does not give up; instead, he shows patience. He thinks about what matters most, which leads him to wait for the dog to approach him."},"",{"choice":"The story ends before the problem is addressed.","category":"ignoring story structure","reason":"The text describes a clear progression from the dog being shy to the dog resting its head beside Caleb. This shows that the initial problem of the dog being afraid has been resolved."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":174,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0175","version":3,"contentHash":"sha256:20b406cd7d4a6fccccd4bfc319d4c329aca58dfe61ff8636dbb5cf1738846c76","question":"Read the story. Grade 5 challenge story: Jada was at a rainy field trip when the outdoor scavenger hunt had to be canceled. At first, the situation seemed discouraging. Instead of reacting too quickly, Jada thought about what mattered most: she wanted the trip to stay interesting even after plans changed. Then she helped classmates create an indoor museum hunt using exhibit clues. In the end, the class discovered details they might have missed.\n\nWhat most likely motivates Jada's actions?","choices":["Jada is trying to avoid helping anyone.","Jada wants to make the problem worse.","Jada hopes nobody notices the problem.","She wanted the trip to stay interesting even after plans changed."],"correct":3,"studyAid":{"definition":"Motivation is the 'why' behind a character's actions. It is the reason or goal that drives someone to behave a certain way in a story.","example":"If a character shares their lunch, their motivation might be kindness. If they study hard, their motivation might be a desire to learn or earn a good grade.","strategyClue":"Look for sentences in the text that follow a character's thought process or explain their values. Ask yourself, 'What result does the character want to achieve through this action?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She wanted the trip to stay interesting even after plans changed. The story explicitly states that Jada 'thought about what mattered most' and acted to ensure the trip remained engaging for everyone despite the canceled outdoor hunt.","incorrect":[{"choice":"Jada is trying to avoid helping anyone.","category":"character motivation error","reason":"This is incorrect because the story says Jada 'helped classmates create an indoor museum hunt.' She is being helpful, not avoidant."},{"choice":"Jada wants to make the problem worse.","category":"character motivation error","reason":"The story shows Jada finding a positive solution to the canceled trip. Making the situation worse would be the opposite of her actions."},{"choice":"Jada hopes nobody notices the problem.","category":"character motivation error","reason":"Jada does not hide the problem; she addresses it directly by creating a new activity for the class to participate in together."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":175,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0176","version":3,"contentHash":"sha256:6b58ee232b2dcbaf602853838fac30376b0d9e597328313def115458843802aa","question":"Read the story. Grade 5 challenge story: Omar was at the computer lab when his slideshow disappeared when the program froze. At first, the situation seemed discouraging. Instead of reacting too quickly, Omar thought about what mattered most: he wanted to recover his work instead of quitting. Then he checked the autosave folder and rebuilt two missing slides from his notes. In the end, his presentation was ready before class ended.\n\nWhich word best describes Omar?","choices":["determined","careless","boastful","impatient"],"correct":0,"studyAid":{"definition":"To find a character's trait, look at what they do and how they act when they face a problem in a story.","example":"If a character shares their lunch with a hungry friend, they are generous. If a character studies for hours to pass a hard test, they are hardworking.","strategyClue":"Look for specific actions in the text that show how the character handled the difficult situation. Ask yourself: 'Does this choice match the actions Omar took when his program crashed?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: determined. Omar is determined because he stayed focused on his goal to recover his work, rebuilt his missing slides, and finished before class, despite the setback.","incorrect":["",{"choice":"careless","category":"character trait error","reason":"Omar was actually very careful and diligent. He didn't just give up; he searched through his files and used his notes to fix his slides."},{"choice":"boastful","category":"character trait error","reason":"The story never mentions Omar bragging or talking about himself. He was busy working quietly to solve his problem, not showing off."},{"choice":"impatient","category":"character trait error","reason":"The text says Omar decided against 'reacting too quickly.' Because he took the time to think instead of getting angry or quitting, he acted the opposite of impatient."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":176,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0177","version":3,"contentHash":"sha256:3f30f9b014fbef72f89d2c06539b58e0cba4935653902d1bdb8ee1cb170c7c51","question":"Read the story. Grade 5 challenge story: Nora was at the neighborhood sidewalk when an elderly neighbor struggled to carry groceries up the steps. At first, the situation seemed discouraging. Instead of reacting too quickly, Nora thought about what mattered most: she saw a way to make someone's task easier. Then Nora asked permission, carried two light bags, and held the gate open. In the end, the neighbor thanked her and invited her to pick tomatoes later.\n\nWhat is the story's main problem?","choices":["Nora wants to leave the setting before anything happens.","an elderly neighbor struggled to carry groceries up the steps","Nora cannot remember anyone's name.","The story has no problem to solve."],"correct":1,"studyAid":{"definition":"The 'problem' or 'conflict' in a story is the struggle or challenge a character must face or overcome.","example":"A character loses their house key (problem); a student forgets their homework at home (problem).","strategyClue":"Look for a sentence where someone is having a hard time or facing a difficult task. Once you find that 'trouble,' you have found the main problem.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: an elderly neighbor struggled to carry groceries up the steps. A problem in a story is a challenge or struggle a character faces. The elderly neighbor's difficulty in moving the groceries is the central conflict that triggers Nora's actions.","incorrect":[{"choice":"Nora wants to leave the setting before anything happens.","category":"misreading the text","reason":"The text does not state that Nora wants to leave. In fact, she observes the situation and chooses to help instead of walking away."},"",{"choice":"Nora cannot remember anyone's name.","category":"not supported by text","reason":"The story never mentions Nora having trouble with names. This detail is not part of the narrative or the problem Nora encounters."},{"choice":"The story has no problem to solve.","category":"misidentifying story conflict","reason":"Every story needs a conflict or problem. In this case, the neighbor's struggle creates a need that Nora fulfills."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":177,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0178","version":3,"contentHash":"sha256:11b6aa77f4bcf684dfe40d91c3a5feeeaa146ebf4e91dec81611f09c7c370966","question":"Read the story. Grade 5 challenge story: Ben was at the chess club table when he lost three games in a row. At first, the situation seemed discouraging. Instead of reacting too quickly, Ben thought about what mattered most: he wanted to learn from mistakes instead of hiding them. Then he asked his opponent to show the move that trapped his queen. In the end, he used the lesson to avoid the trap in the next game.\n\nWhere does the story mainly take place?","choices":["on a mountain trail","inside a grocery store","the chess club table","at a train station"],"correct":2,"studyAid":{"definition":"The setting is the time and place where a story takes place. Authors often state the setting clearly in the opening sentences of a story.","example":"In a forest, at a school, during a rainy afternoon.","strategyClue":"Scan the first sentence of the story for a prepositional phrase that describes a specific location, then check if the rest of the details in the text match that setting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the chess club table. The first sentence explicitly states, 'Ben was at the chess club table,' identifying the location where the events of the story begin and unfold.","incorrect":[{"choice":"on a mountain trail","category":"setting mismatch","reason":"There is no mention of mountains or hiking trails in the text. The story is clearly centered around a game of chess."},{"choice":"inside a grocery store","category":"setting mismatch","reason":"The story describes Ben playing games and analyzing moves, which does not happen in a grocery store setting."},"",{"choice":"at a train station","category":"setting mismatch","reason":"The text mentions a club table and chess pieces, not a train station. This setting would contradict the activity taking place."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":178,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0179","version":3,"contentHash":"sha256:dd7589f140a734a783143c8e50e0a1dff5a7afe37112a21d47ee2d1447cd8617","question":"Read the story. Grade 5 challenge story: Talia was at the school hallway after dismissal when she found a wallet with lunch money and a student ID. At first, the situation seemed discouraging. Instead of reacting too quickly, Talia thought about what mattered most: she knew the wallet belonged to someone else. Then she took it to the office before leaving for practice. In the end, the owner got the wallet back before the buses left.\n\nHow is the problem resolved?","choices":["The story ends before the problem is addressed.","Talia decides the problem is impossible.","An adult solves the problem without the character doing anything.","the owner got the wallet back before the buses left"],"correct":3,"studyAid":{"definition":"A resolution is how a story's problem or conflict is finally settled or fixed.","example":"Problem: A dog runs away. Resolution: The owner finds the dog at the park. Problem: A girl loses her keys. Resolution: She finds them in her backpack.","strategyClue":"Look for the sentence near the very end of the paragraph that describes a positive outcome related to the item Talia found.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the owner got the wallet back before the buses left. This sentence directly describes the final outcome, confirming that Talia's action resulted in the lost item being returned to its owner.","incorrect":[{"choice":"The story ends before the problem is addressed.","category":"misreading the conclusion","reason":"The story explicitly states that the owner received the wallet, so the problem was indeed addressed and solved before the ending."},{"choice":"Talia decides the problem is impossible.","category":"incorrect character action","reason":"Talia does not give up; instead, she thinks about the right thing to do and takes the wallet to the office to help the owner."},{"choice":"An adult solves the problem without the character doing anything.","category":"misidentifying the solution","reason":"The story highlights Talia's initiative in taking the wallet to the office, showing that she is the one who initiates the resolution."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":179,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0180","version":4,"contentHash":"sha256:c147829a1983d755069778a3042b7221f65d4fdb7022a2d9540e4dce04155fd6","question":"Read the story. Grade 5 challenge story: Diego was at the creek behind the park when he saw that stepping stones had shifted after heavy rain. At first, the situation seemed discouraging. Instead of reacting too quickly, Diego thought about what mattered most: he wanted others to stay safe. Then he warned younger children to use the bridge and told a ranger. In the end, the crossing was closed until it could be repaired.\n\nWhat most likely motivates Diego's actions?","choices":["He wanted others to stay safe.","Diego wants to make the problem worse.","Diego hopes nobody notices the problem.","Diego is trying to avoid helping anyone."],"correct":0,"studyAid":{"definition":"Character motivation is the reason a character says, thinks, or does something in a story.","example":"A character shares a toy to make a friend happy; a character practices piano because they want to perform in the recital.","strategyClue":"Look for sentences in the text that directly explain a character's internal feelings or their specific goals right before they take action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: He wanted others to stay safe. The text explicitly states, 'he wanted others to stay safe' when describing his reasoning for warning the children and contacting the ranger.","incorrect":["",{"choice":"Diego wants to make the problem worse.","category":"opposite character motivation","reason":"The text shows Diego taking positive steps like warning children and notifying a ranger, which are actions meant to solve a problem, not make it worse."},{"choice":"Diego hopes nobody notices the problem.","category":"misunderstanding character intent","reason":"If Diego wanted no one to notice, he would not have told a ranger or warned the younger children. His actions show he wants to bring attention to the safety hazard."},{"choice":"Diego is trying to avoid helping anyone.","category":"ignoring textual evidence","reason":"Diego is clearly being helpful by ensuring the safety of others at the creek. Avoiding help would mean ignoring the dangerous stones entirely."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":180,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0181","version":3,"contentHash":"sha256:0d24b2ff778363382ffd519dc25a251ade57f2041220c3a38512e0eaee9d64d2","question":"Read the story and answer the question. Who is telling the story?","choices":["Lin da","Kathy","Ann","Sue"],"correct":3,"explanation":{"correct":"Answer: Sue. The story explicitly mentions Sue as the narrator using the first-person perspective, such as saying 'I saw the dog.'","incorrect":[{"choice":"Lin da","category":"incorrect character identification","reason":"Lin da is mentioned as a character in the story, but the text describes Lin da in the third person, meaning she is not the one telling the story."},{"choice":"Kathy","category":"incorrect character identification","reason":"Kathy is a character the narrator interacts with, but the story is not told from her perspective. Look for pronouns like 'I' or 'my' to identify the narrator."},{"choice":"Ann","category":"incorrect character identification","reason":"Ann is another character present in the scene, but she is never the narrator. Review the sentences to see which character's thoughts and actions are directly described by the storyteller."},""]},"studyAid":{"definition":"The narrator is the person telling the story. First-person narrators use words like 'I', 'me', and 'my' to share their own experiences.","example":"'I walked to the store' (First-person narrator), 'She walked to the store' (Third-person perspective)","strategyClue":"Scan the text for the words 'I' or 'my'. The character who is speaking or thinking using those words is the one telling the story.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"analyze-with-context","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-story-elements","sourceFile":"Basic-4_Informational Text.pdf","sourceQuestionNumber":9,"sourceCategory":"informational-text","sourceGrade":3,"sequence":181,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-story-elements-q0182","version":5,"contentHash":"sha256:36d8b603cfbd881158de666dbc6ada5e2d58fe183a7331f97d4653fe54445e7f","question":"What is the purpose of using dialogue in a story?","choices":["to make a story longer","to add vivid details and descriptions","to demonstrate how to properly punctuate dialogue","to bring characters to life and communicate emotions"],"correct":3,"explanation":{"correct":"Answer: to bring characters to life and communicate emotions. Dialogue allows readers to hear a character's unique voice, witness their personality, and understand how they feel through their spoken words.","incorrect":[{"choice":"to make a story longer","category":"incorrect writing purpose","reason":"Writing isn't just about length. Using dialogue solely to add pages usually makes a story feel slow and boring rather than engaging."},{"choice":"to add vivid details and descriptions","category":"descriptive writing confusion","reason":"Vivid details and descriptions are best handled through sensory language and imagery, while dialogue is specifically for what characters say to each other."},{"choice":"to demonstrate how to properly punctuate dialogue","category":"functional writing confusion","reason":"While dialogue needs correct punctuation, the primary goal of writing a story is to entertain and inform the reader, not to provide a grammar lesson."},""]},"studyAid":{"definition":"Dialogue is the conversation between characters in a story, used to reveal their personalities and move the plot forward.","example":"'I'm so excited for the party!' shouted Maya. (This shows Maya is happy and enthusiastic.)","strategyClue":"Ask yourself: 'Does this choice explain how the characters show their feelings and interact, or does it focus on a technical or external part of the story?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"analyze-with-context","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reading-comprehension-story-elements","sourceFile":"Proficient-12_Informational Text.pdf","sourceQuestionNumber":7,"sourceCategory":"informational-text","sourceGrade":3,"sequence":182,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-story-elements"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-story-elements"] = chunkSet;
  }
})();
